// v1.7d: put a SOLD listing back in the shop with one click. The
// password is the one MovMail generated when the mailbox was created
// — Mov never set one himself and never needs to type one: the
// server reuses the stored credentials. The Mail.tm login is re-run
// first, so a dead mailbox (deleted account) can never be re-listed
// — it answers 400 with the honest login error instead. On success
// the listing is 'active' again at the same price / title / token /
// logo, health 'good', and created_at refreshed so it shows the
// "New" badge in the shop like a fresh listing.
async function handleAdminMarketListingRelist(req, res, id) {
  const listing = await getListing(id);
  if (!listing) {
    sendJson(res, 404, { ok: false, error: "listing not found" });
    return;
  }
  if (listing.status !== "sold") {
    sendJson(res, 400, { ok: false, error: "only a sold listing can be put back in the shop" });
    return;
  }
  const login = await mailTmLogin(listing.email, listing.password);
  if (!login.ok) {
    sendJson(res, 400, { ok: false, error: login.error });
    return;
  }
  let updated = null;
  if (!USE_MEMORY_STORE) {
    const r = await dbPool.query(
      "UPDATE market_listings SET status = 'active', health = 'good', health_reason = '', " +
        "health_bad_since = NULL, health_checked_at = NOW(), created_at = NOW() WHERE id = $1 RETURNING *",
      [Number(id)]
    );
    updated = r.rows[0] || null;
  } else {
    const row = mem.listings.get(Number(id));
    if (row) {
      row.status = "active";
      row.health = "good";
      row.health_reason = "";
      row.health_bad_since = null;
      row.health_checked_at = new Date().toISOString();
      row.created_at = new Date().toISOString();
    }
    updated = row || null;
  }
  if (!updated) {
    sendJson(res, 404, { ok: false, error: "listing not found" });
    return;
  }
  sendJson(res, 200, { ok: true, listing: listingAdminFromRow(updated) });
}

// Decode the Mail.tm JWT payload (base64, no signature check — we
// only read the account id claim) as a fallback when POST /token
// does not return the id directly.
function jwtAccountId(token) {
  try {
    const parts = String(token || "").split(".");
    if (parts.length !== 3) return "";
    const payload = JSON.parse(
      Buffer.from(parts[1].replace(/-/g, "+").replace(/_/g, "/"), "base64").toString("utf8")
    );
    return String(payload.sub || payload.id || "");
  } catch (_) {
    return "";
  }
}

/* ---------- v1.10: delete requests (BLOCKED) ----------
   Mov's rule (2026-11-27, permanent): NO ONE deletes a shop email
   without his permission. Pressing Delete on a listed mailbox does
   NOT delete it — it files a request here. The mailbox stays alive
   (codes keep arriving) with a "BLOCKED — waiting" badge until Mov
   approves (real delete, v1.9d path) or rejects it. A request the
   admin never answers EXPIRES after 24h and the mailbox goes back
   to normal. The proxy still refuses every DELETE /accounts, so
   this is the only way a listed account can ever die. */
function deleteRequestFromRow(r) {
  if (!r) return null;
  return {
    id: r.id,
    listingId: r.listing_id,
    // `buyer_gmail` is the requester's gmail (seller or buyer).
    requesterGmail: r.buyer_gmail || "",
    address: r.address || "",
    listingEmail: r.listing_email || r.address || "",
    listingTitle: r.listing_title || "",
    status: r.status || "pending",
    createdAt: toIso(r.created_at),
    expiresAt: toIso(r.expires_at),
    decidedAt: toIso(r.decided_at),
  };
}

// Lazy expiry: pending requests past 24h become 'expired'. Runs at
// the start of every delete-request read (same pattern as
// expireRedListings), so no request can ever be approved late.
async function expireDeleteRequests() {
  if (!USE_MEMORY_STORE) {
    await dbPool.query(
      "UPDATE market_delete_requests SET status = 'expired' WHERE status = 'pending' AND expires_at < NOW()"
    );
    return;
  }
  const now = Date.now();
  for (const row of mem.deleteRequests) {
    if (row.status === "pending" && row.expires_at && Date.parse(row.expires_at) < now) {
      row.status = "expired";
    }
  }
}

function withDeleteRequestListing(row) {
  if (!row) return null;
  if (!USE_MEMORY_STORE) return row;
  const l = mem.listings.get(row.listing_id);
  return { ...row, listing_email: l ? l.email : "", listing_title: l ? l.title || "" : "" };
}

async function getDeleteRequest(id) {
  const n = Number(id);
  if (!Number.isInteger(n)) return null;
  if (!USE_MEMORY_STORE) {
    const r = await dbPool.query(
      "SELECT dr.*, l.email AS listing_email, l.title AS listing_title FROM market_delete_requests dr" +
        " LEFT JOIN market_listings l ON l.id = dr.listing_id WHERE dr.id = $1 LIMIT 1",
      [n]
    );
    return r.rows[0] || null;
  }
  return withDeleteRequestListing(mem.deleteRequests.find((x) => x.id === n) || null);
}

async function findPendingDeleteRequest(listingId, gmail) {
  const n = Number(listingId);
  const g = String(gmail || "").trim().toLowerCase();
  if (!Number.isInteger(n) || !g) return null;
  await expireDeleteRequests();
  if (!USE_MEMORY_STORE) {
    const r = await dbPool.query(
      "SELECT dr.*, l.email AS listing_email, l.title AS listing_title FROM market_delete_requests dr" +
        " LEFT JOIN market_listings l ON l.id = dr.listing_id" +
        " WHERE dr.listing_id = $1 AND dr.buyer_gmail = $2 AND dr.status = 'pending' AND dr.expires_at >= NOW()" +
        " ORDER BY dr.created_at DESC LIMIT 1",
      [n, g]
    );
    return r.rows[0] || null;
  }
  const now = Date.now();
  const rows = mem.deleteRequests
    .filter(
      (x) =>
        x.listing_id === n &&
        String(x.buyer_gmail || "").toLowerCase() === g &&
        x.status === "pending" &&
        x.expires_at &&
        Date.parse(x.expires_at) >= now
    )
    .sort((a, b) => String(b.created_at || "").localeCompare(String(a.created_at || "")));
  return withDeleteRequestListing(rows[0] || null);
}

async function createDeleteRequest(listing, gmail) {
  const g = String(gmail || "").trim().toLowerCase();
  if (!USE_MEMORY_STORE) {
    const r = await dbPool.query(
      "INSERT INTO market_delete_requests (listing_id, buyer_gmail, address, status, expires_at)" +
        " VALUES ($1,$2,$3,'pending', NOW() + INTERVAL '24 hours') RETURNING *",
      [listing.id, g, listing.email || ""]
    );
    return r.rows[0];
  }
  const now = new Date();
  const row = {
    id: mem.deleteRequestSeq++,
    listing_id: listing.id,
    buyer_gmail: g,
    address: listing.email || "",
    status: "pending",
    created_at: now.toISOString(),
    expires_at: new Date(now.getTime() + 24 * 60 * 60 * 1000).toISOString(),
    decided_at: null,
  };
  mem.deleteRequests.push(row);
  return row;
}

async function decideDeleteRequest(id, status) {
  const n = Number(id);
  if (!USE_MEMORY_STORE) {
    const r = await dbPool.query(
      "UPDATE market_delete_requests SET status = $2, decided_at = NOW() WHERE id = $1 RETURNING *",
      [n, status]
    );
    return r.rows[0] || null;
  }
  const row = mem.deleteRequests.find((x) => x.id === n) || null;
  if (!row) return null;
  row.status = status;
  row.decided_at = new Date().toISOString();
  return row;
}

async function listDeleteRequestsForGmail(gmail) {
  const g = String(gmail || "").trim().toLowerCase();
  await expireDeleteRequests();
  if (!g) return [];
  if (!USE_MEMORY_STORE) {
    const r = await dbPool.query(
      "SELECT dr.*, l.email AS listing_email, l.title AS listing_title FROM market_delete_requests dr" +
        " LEFT JOIN market_listings l ON l.id = dr.listing_id WHERE dr.buyer_gmail = $1 ORDER BY dr.created_at DESC",
      [g]
    );
    return r.rows.map(deleteRequestFromRow);
  }
  return mem.deleteRequests
    .filter((x) => String(x.buyer_gmail || "").toLowerCase() === g)
    .sort((a, b) => String(b.created_at || "").localeCompare(String(a.created_at || "")))
    .map((x) => deleteRequestFromRow(withDeleteRequestListing(x)));
}

async function listAllDeleteRequests() {
  await expireDeleteRequests();
  if (!USE_MEMORY_STORE) {
    const r = await dbPool.query(
      "SELECT dr.*, l.email AS listing_email, l.title AS listing_title FROM market_delete_requests dr" +
        " LEFT JOIN market_listings l ON l.id = dr.listing_id ORDER BY (dr.status = 'pending') DESC, dr.created_at DESC"
    );
    return r.rows.map(deleteRequestFromRow);
  }
  return mem.deleteRequests
    .slice()
    .sort((a, b) => {
      const pa = a.status === "pending" ? 0 : 1;
      const pb = b.status === "pending" ? 0 : 1;
      if (pa !== pb) return pa - pb;
      return String(b.created_at || "").localeCompare(String(a.created_at || ""));
    })
    .map((x) => deleteRequestFromRow(withDeleteRequestListing(x)));
}

// A listing by its full email (any status except 'removed' — a
// removed listing's mailbox is already gone). Used by the website
// to resolve a listing id for a saved row that never got one
// stamped (e.g. a seller copy listed from the admin panel).
async function getListingByEmail(email) {
  const e = String(email || "").trim().toLowerCase();
  if (!e) return null;
  if (!USE_MEMORY_STORE) {
    const r = await dbPool.query(
      "SELECT * FROM market_listings WHERE LOWER(email) = $1 AND status <> 'removed' ORDER BY created_at DESC LIMIT 1",
      [e]
    );
    return r.rows[0] || null;
  }
  const rows = [...mem.listings.values()]
    .filter((x) => String(x.email || "").toLowerCase() === e && x.status !== "removed")
    .sort((a, b) => String(b.created_at || "").localeCompare(String(a.created_at || "")));
  return rows[0] || null;
}

// The REAL delete of a listed Mail.tm account, shared by the v1.9d
// admin "Delete forever" button and by an approved v1.10 delete
// request. Returns {ok:true, already} or {ok:false, error}. It never
// logs by itself — the caller writes the security event (the two
// paths have different types) — and it never touches request rows.
async function deleteListingAccountNow(listing) {
  const login = await mailTmLogin(listing.email, listing.password);
  if (!login.ok) {
    const err = String(login.error || "");
    if (err.indexOf("no longer exists") !== -1) {
      // Already dead on Mail.tm: nothing left to delete — just take
      // the listing out of the shop.
      await removeListing(listing.id);
      return { ok: true, already: true };
    }
    return { ok: false, error: login.error };
  }
  // POST /token returns the account id as `id` (the site has always
  // taken it from there); the JWT `sub` claim is the fallback.
  const accountId = String(login.id || "") || jwtAccountId(login.token);
  if (!accountId) {
    return { ok: false, error: "could not determine Mail.tm account id" };
  }
  let delRes = null;
  try {
    const ctl = new AbortController();
    const timer = setTimeout(() => ctl.abort(), 15000);
    delRes = await fetch(UPSTREAM + "/accounts/" + encodeURIComponent(accountId), {
      method: "DELETE",
      headers: { Authorization: "Bearer " + login.token, Accept: "application/json" },
      signal: ctl.signal,
    });
    clearTimeout(timer);
  } catch (err) {
    return { ok: false, error: "Mail.tm unreachable: " + String((err && err.message) || err) };
  }
  if (delRes.status !== 204 && delRes.status !== 200 && delRes.status !== 404) {
    let msg = "Mail.tm delete failed (HTTP " + delRes.status + ")";
    try {
      const d = JSON.parse(await delRes.text());
      if (d && (d.message || d.detail || d.error)) msg = String(d.message || d.detail || d.error);
    } catch (_) {}
    return { ok: false, error: msg };
  }
  // 204/200 = deleted now; 404 = already gone — either way the
  // account no longer exists, so the listing leaves the shop.
  await removeListing(listing.id);
  return { ok: true, already: delRes.status === 404 };
}

async function handleMarketDeleteRequestsCreate(req, res) {
  const body = await readJsonBody(req, res, 64 * 1024);
  if (!body) return;
  const gmail = String(body.gmail || "").trim().toLowerCase();
  const listingId = Number(body.listingId);
  if (!gmail || !Number.isInteger(listingId)) {
    sendJson(res, 400, { ok: false, error: "gmail and listingId required" });
    return;
  }
  const listing = await getListing(listingId);
  if (!listing) {
    sendJson(res, 404, { ok: false, error: "listing not found" });
    return;
  }
  // Only the seller of this listing or its approved buyer may ask
  // for it to be deleted — anyone else gets 403 and no request row.
  const isSeller = String(listing.seller_gmail || "").toLowerCase() === gmail;
  const order = isSeller ? null : await findApprovedOrder(listingId, gmail);
  if (!isSeller && !order) {
    sendJson(res, 403, { ok: false, error: "only the seller or the buyer of this listing can request deletion" });
    return;
  }
  const existing = await findPendingDeleteRequest(listingId, gmail);
  if (existing) {
    sendJson(res, 200, { ok: true, already: true, request: deleteRequestFromRow(existing) });
    return;
  }
  const row = await createDeleteRequest(listing, gmail);
  try {
    await logSecurityEvent(gmail, "delete_request_created", "listing " + listingId + " " + (listing.email || ""));
  } catch (_) {}
  sendJson(res, 200, {
    ok: true,
    already: false,
    request: deleteRequestFromRow({ ...row, listing_email: listing.email || "", listing_title: listing.title || "" }),
  });
}

async function handleMarketDeleteRequestsList(req, res, url) {
  const gmail = (url.searchParams.get("gmail") || "").trim().toLowerCase();
  if (!gmail) {
    sendJson(res, 400, { ok: false, error: "gmail query param required" });
    return;
  }
  sendJson(res, 200, await listDeleteRequestsForGmail(gmail));
}

async function handleMarketListingByAddress(req, res, url) {
  const address = (url.searchParams.get("address") || "").trim().toLowerCase();
  const gmail = (url.searchParams.get("gmail") || "").trim().toLowerCase();
  if (!address || !gmail) {
    sendJson(res, 400, { ok: false, error: "address and gmail query params required" });
    return;
  }
  const listing = await getListingByEmail(address);
  if (!listing) {
    sendJson(res, 200, { listingId: null });
    return;
  }
  const isSeller = String(listing.seller_gmail || "").toLowerCase() === gmail;
  const order = isSeller ? null : await findApprovedOrder(listing.id, gmail);
  sendJson(res, 200, { listingId: isSeller || order ? listing.id : null });
}

async function handleAdminDeleteRequestsList(req, res) {
  sendJson(res, 200, await listAllDeleteRequests());
}

async function handleAdminDeleteRequestDecide(req, res, id, action) {
  const row = await getDeleteRequest(id);
  if (!row) {
    sendJson(res, 404, { ok: false, error: "delete request not found" });
    return;
  }
  if (row.status !== "pending") {
    sendJson(res, 400, { ok: false, error: "delete request is " + row.status });
    return;
  }
  if (row.expires_at && Date.parse(toIso(row.expires_at)) < Date.now()) {
    // Lazy expiry (also runs on list reads): an unanswered request
    // past 24h can never be approved — flip it and refuse.
    await decideDeleteRequest(row.id, "expired");
    sendJson(res, 400, { ok: false, error: "delete request expired" });
    return;
  }
  if (action === "reject") {
    await decideDeleteRequest(row.id, "rejected");
    sendJson(res, 200, { ok: true, request: deleteRequestFromRow(await getDeleteRequest(id)) });
    return;
  }
  // Approve: the real delete (v1.9d path). The listing may already
  // be gone (removed by Delete forever) — then there is nothing to
  // delete and the request just closes as approved.
  const listing = await getListing(row.listing_id);
  if (!listing || listing.status === "removed") {
    await decideDeleteRequest(row.id, "approved");
    try {
      await logSecurityEvent("", "admin_delete_request_approved", "listing " + row.listing_id + " (already removed) requested by " + (row.buyer_gmail || ""));
    } catch (_) {}
    sendJson(res, 200, { ok: true, already: true, request: deleteRequestFromRow(await getDeleteRequest(id)) });
    return;
  }
  const done = await deleteListingAccountNow(listing);
  if (!done.ok) {
    sendJson(res, 400, { ok: false, error: done.error });
    return;
  }
  await decideDeleteRequest(row.id, "approved");
  try {
    await logSecurityEvent("", "admin_delete_request_approved", "listing " + row.listing_id + " " + (listing.email || "") + " requested by " + (row.buyer_gmail || ""));
  } catch (_) {}
  sendJson(res, 200, { ok: true, already: done.already, request: deleteRequestFromRow(await getDeleteRequest(id)) });
}

// v1.9d: ADMIN-ONLY permanent delete of a listed mailbox — the ONE
// exception to the v1.9c proxy block. Mov's rule (2026-11-27,
// permanent): NO ONE may delete a MovMail email except Mov himself,
// through this admin button. The website has no delete path (its
// Delete is local-only) and the generic forwarder refuses every
// DELETE /accounts, so this handler calls Mail.tm DIRECTLY (same
// UPSTREAM + fetch path as mailTmLogin), never through the
// forwarder. Requires {confirm:true} in the body, so an accidental
// call can never delete. On success the listing becomes 'removed'
// and a security event is written. If the account is already dead
// on Mail.tm (login: "no longer exists") that is NOT an error: the
// listing is just marked removed. Any other login failure, a missing
// account id, or a failed DELETE answers 400 and deletes NOTHING.
async function handleAdminMarketListingDeleteAccount(req, res, id) {
  const body = await readJsonBody(req, res, 64 * 1024);
  if (!body) return;
  if (body.confirm !== true) {
    sendJson(res, 400, { ok: false, error: "confirm is required" });
    return;
  }
  const listing = await getListing(id);
  if (!listing) {
    sendJson(res, 404, { ok: false, error: "listing not found" });
    return;
  }
  if (listing.status === "removed") {
    sendJson(res, 200, { ok: true, already: true, listing: listingAdminFromRow(listing) });
    return;
  }
  // v1.10: the delete itself lives in deleteListingAccountNow
  // (shared with approved delete requests).
  const done = await deleteListingAccountNow(listing);
  if (!done.ok) {
    sendJson(res, 400, { ok: false, error: done.error });
    return;
  }
  try {
    await logSecurityEvent("", "admin_account_delete", "listing " + id + " " + listing.email + (done.already ? " (already dead)" : ""));
  } catch (_) {}
  const row = await getListing(id);
  sendJson(res, 200, { ok: true, already: done.already, listing: listingAdminFromRow(row || listing) });
}

// v1.3: re-run the Mail.tm login for one listing and apply the
// result (good on success, bad on wrong credentials, unchanged on
// upstream outage). Returns the updated listing (admin shape).
async function handleAdminMarketListingCheck(req, res, id) {
  const listing = await getListing(id);
  if (!listing) {
    sendJson(res, 404, { ok: false, error: "listing not found" });
    return;
  }
  const updated = await checkListingHealth(listing);
  sendJson(res, 200, { ok: true, listing: listingAdminFromRow(updated) });
}

// v1.3: manual health override. Setting 'bad' starts the 24h red
// clock (keeps the original bad_since when already bad); setting
// 'good' clears it.
async function handleAdminMarketListingHealth(req, res, id) {
  const body = await readJsonBody(req, res, 64 * 1024);
  if (!body) return;
  const health = String(body.health || "").trim().toLowerCase();
  if (health !== "good" && health !== "bad") {
    sendJson(res, 400, { ok: false, error: 'health must be "good" or "bad"' });
    return;
  }
  const listing = await getListing(id);
  if (!listing) {
    sendJson(res, 404, { ok: false, error: "listing not found" });
    return;
  }
  let badSince = null;
  if (health === "bad") {
    badSince =
      healthOf(listing) === "bad" && listing.health_bad_since
        ? listing.health_bad_since
        : new Date();
  }
  // v1.3 D: a manual toggle to 'bad' records its marker as the
  // reason; a toggle to 'good' clears the reason (see
  // updateListingHealth). A manual 'good' stands until a new
  // matching message is saved or the next stale re-check runs.
  const updated = await updateListingHealth(
    listing.id,
    health,
    badSince,
    health === "bad" ? "Manual: marked bad by admin" : null
  );
  sendJson(res, 200, { ok: true, listing: listingAdminFromRow(updated) });
}

async function handleAdminMarketOrdersList(req, res) {
  sendJson(res, 200, await listAllOrders());
}

async function handleAdminMarketOrderDecide(req, res, id, action) {
  const decided = await decideMarketOrder(Number(id), action === "approve");
  if (!decided) {
    sendJson(res, 404, { ok: false, error: "order not found" });
    return;
  }
  if (decided.error) {
    sendJson(res, 400, { ok: false, error: decided.error });
    return;
  }
  sendJson(res, 200, { ok: true });
}

async function handleApi(req, res, url) {
  const p = url.pathname;
  try {
    if (req.method === "POST" && p === "/api/accounts/upsert") return handleApiAccountsUpsert(req, res);
    if (req.method === "GET" && p === "/api/accounts/me") return handleApiAccountsMe(req, res, url);
    if (req.method === "GET" && p === "/api/blocked") return handleApiBlocked(req, res, url);
    if (req.method === "POST" && p === "/api/redeem") return handleApiRedeem(req, res);
    if (req.method === "POST" && p === "/api/receipts") return handleApiReceiptsCreate(req, res);
    if (req.method === "POST" && p === "/api/security/event") return handleApiSecurityEvent(req, res);
    if (req.method === "GET" && p === "/api/notifications") return handleApiNotificationsList(req, res, url);
    if (req.method === "POST" && p === "/api/notifications/read") return handleApiNotificationsRead(req, res);
    if (req.method === "POST" && p === "/api/market/listings") return handleMarketListingsCreate(req, res);
    if (req.method === "GET" && p === "/api/market/listings") return handleMarketListingsList(req, res);
    if (req.method === "POST" && p === "/api/market/orders") return handleMarketOrdersCreate(req, res);
    if (req.method === "GET" && p === "/api/market/orders") return handleMarketOrdersList(req, res, url);
    if (req.method === "POST" && p === "/api/market/restore") return handleMarketRestore(req, res);
    if (req.method === "POST" && p === "/api/market/delete-requests") return handleMarketDeleteRequestsCreate(req, res);
    if (req.method === "GET" && p === "/api/market/delete-requests") return handleMarketDeleteRequestsList(req, res, url);
    if (req.method === "GET" && p === "/api/market/listings/by-address") return handleMarketListingByAddress(req, res, url);
    const mMktRep = /^\/api\/market\/orders\/(\d+)\/report$/.exec(p);
    if (req.method === "POST" && mMktRep) return handleMarketOrderReport(req, res, mMktRep[1]);
    if (p.startsWith("/api/admin/")) {
      if (!requireAdmin(req, res)) return;
      if (req.method === "GET" && p === "/api/admin/users") return handleAdminUsers(req, res);
      if (req.method === "POST" && p === "/api/admin/block") return handleAdminBlock(req, res);
      if (req.method === "POST" && p === "/api/admin/codes") return handleAdminCodesCreate(req, res);
      if (req.method === "GET" && p === "/api/admin/codes") return handleAdminCodesList(req, res);
      const mCode = /^\/api\/admin\/codes\/([^/]+)\/(disable|activate)$/.exec(p);
      if (req.method === "POST" && mCode) return handleAdminCodeToggle(req, res, mCode[1], mCode[2]);
      if (req.method === "POST" && p === "/api/admin/notify") return handleAdminNotify(req, res);
      if (req.method === "POST" && p === "/api/admin/codes/send") return handleAdminCodesSend(req, res);
      if (req.method === "GET" && p === "/api/admin/receipts") return handleAdminReceiptsList(req, res);
      if (req.method === "GET" && p === "/api/admin/notifications") return handleAdminListingNotificationsList(req, res);
      if (req.method === "POST" && p === "/api/admin/notifications/read") return handleAdminListingNotificationsRead(req, res);
      const mNotifFwd = /^\/api\/admin\/notifications\/(\d+)\/forward$/.exec(p);
      if (req.method === "POST" && mNotifFwd) return handleAdminListingNotificationForward(req, res, mNotifFwd[1]);
      if (req.method === "GET" && p === "/api/admin/market/listings") return handleAdminMarketListingsList(req, res);
      if (req.method === "POST" && p === "/api/admin/market/listings") return handleAdminMarketListingsCreate(req, res);
      const mMktList = /^\/api\/admin\/market\/listings\/(\d+)\/remove$/.exec(p);
      if (req.method === "POST" && mMktList) return handleAdminMarketListingRemove(req, res, mMktList[1]);
      const mMktRelist = /^\/api\/admin\/market\/listings\/(\d+)\/relist$/.exec(p);
      if (req.method === "POST" && mMktRelist) return handleAdminMarketListingRelist(req, res, mMktRelist[1]);
      const mMktDelAcc = /^\/api\/admin\/market\/listings\/(\d+)\/delete-account$/.exec(p);
      if (req.method === "POST" && mMktDelAcc) return handleAdminMarketListingDeleteAccount(req, res, mMktDelAcc[1]);
      const mMktCheck = /^\/api\/admin\/market\/listings\/(\d+)\/check$/.exec(p);
      if (req.method === "POST" && mMktCheck) return handleAdminMarketListingCheck(req, res, mMktCheck[1]);
      const mMktHealth = /^\/api\/admin\/market\/listings\/(\d+)\/health$/.exec(p);
      if (req.method === "POST" && mMktHealth) return handleAdminMarketListingHealth(req, res, mMktHealth[1]);
      if (req.method === "GET" && p === "/api/admin/market/orders") return handleAdminMarketOrdersList(req, res);
      if (req.method === "GET" && p === "/api/admin/delete-requests") return handleAdminDeleteRequestsList(req, res);
      const mDelReq = /^\/api\/admin\/delete-requests\/(\d+)\/(approve|reject)$/.exec(p);
      if (req.method === "POST" && mDelReq) return handleAdminDeleteRequestDecide(req, res, mDelReq[1], mDelReq[2]);
      const mMktOrd = /^\/api\/admin\/market\/orders\/(\d+)\/(approve|reject)$/.exec(p);
      if (req.method === "POST" && mMktOrd) return handleAdminMarketOrderDecide(req, res, mMktOrd[1], mMktOrd[2]);
      const mRec = /^\/api\/admin\/receipts\/(\d+)\/(approve|reject)$/.exec(p);
      if (req.method === "POST" && mRec) return handleAdminReceiptDecide(req, res, mRec[1], mRec[2]);
    }
    sendJson(res, 404, { error: "not found" });
  } catch (err) {
    console.error("movmail-proxy: api failed:", err.message);
    sendJson(res, 500, { error: "internal error" });
  }
}

/* ---------- GET /domains cache (5 minutes) ----------
   The domain list almost never changes, but the site asks for it on
   every account creation. Cache successful upstream answers in
   memory so repeated lookups do not hit Mail.tm at all. Only
   successful (2xx) answers are cached; failures are never cached. */
const DOMAINS_CACHE_TTL_MS = 5 * 60 * 1000;
let domainsCache = { at: 0, data: null };

/* ---------- HTTP plumbing ---------- */

function sendJson(res, status, obj) {
  const body = JSON.stringify(obj);
  res.writeHead(status, {
    ...CORS_HEADERS,
    "Content-Type": "application/json",
    "Content-Length": Buffer.byteLength(body),
  });
  res.end(body);
}

function isAllowed(method, pathname) {
  if (method === "GET" && pathname === "/domains") return true;
  if (method === "POST" && pathname === "/accounts") return true;
  if (method === "POST" && pathname === "/token") return true;
  if (method === "GET" && pathname === "/messages") return true;
  if (method === "GET" && /^\/messages\/[^/]+$/.test(pathname)) return true;
  // v1.9c: DELETE is NOT allowed on /accounts/<id> anymore — the
  // explicit guard below refuses it with 403, and this allowlist no
  // longer permits it either, so a delete can never reach Mail.tm.
  if (method === "GET" && /^\/accounts\/[^/]+$/.test(pathname)) return true;
  return false;
}

const server = http.createServer((req, res) => {
  const url = new URL(req.url || "/", "http://localhost");

  // CORS preflight
  if (req.method === "OPTIONS") {
    res.writeHead(204, CORS_HEADERS);
    res.end();
    return;
  }

  // Health check
  if (req.method === "GET" && url.pathname === "/") {
    sendJson(res, 200, { ok: true, service: "movmail-proxy" });
    return;
  }

  // Admin PWA: manifest + logo (PNG bytes embedded as base64 above).
  if (req.method === "GET" && url.pathname === "/admin/manifest.json") {
    sendJson(res, 200, ADMIN_MANIFEST);
    return;
  }
  if (
    req.method === "GET" &&
    (url.pathname === "/admin/logo.png" || url.pathname === "/admin/logo-192.png")
  ) {
    const buf = Buffer.from(
      url.pathname === "/admin/logo.png" ? ADMIN_LOGO_PNG_B64 : ADMIN_LOGO_192_B64,
      "base64"
    );
    res.writeHead(200, {
      ...CORS_HEADERS,
      "Content-Type": "image/png",
      "Content-Length": buf.length,
    });
    res.end(buf);
    return;
  }

  // Admin panel (temporary home on this service)
  if (req.method === "GET" && Object.prototype.hasOwnProperty.call(ADMIN_FILES, url.pathname)) {
    const f = ADMIN_FILES[url.pathname];
    res.writeHead(200, {
      ...CORS_HEADERS,
      "Content-Type": f.type,
      "Content-Length": f.body.length,
    });
    res.end(f.body);
    return;
  }
  if (req.method === "GET" && url.pathname.startsWith("/admin/")) {
    sendJson(res, 404, { error: "not found" });
    return;
  }

  // Saved messages (served locally from Postgres, not proxied)
  if (req.method === "GET" && url.pathname === "/saved") {
    handleSavedList(req, res, url);
    return;
  }
  if (req.method === "DELETE" && url.pathname === "/saved") {
    handleSavedDelete(req, res, url);
    return;
  }
  if (req.method === "GET" && /^\/saved\/[^/]+$/.test(url.pathname)) {
    handleSavedOne(req, res, url);
    return;
  }

  // Accounts / admin API (served locally, not proxied)
  if (url.pathname.startsWith("/api/")) {
    // Hardening (2026-11-26): handleApi returns handler promises without
    // awaiting them, so an async DB error inside a handler would reject
    // unhandled and crash the whole proxy process. Catch it here and
    // answer 500 instead of dying.
    handleApi(req, res, url).catch((err) => {
      console.error("movmail-proxy: api failed:", err && err.message ? err.message : err);
      try { if (!res.headersSent) sendJson(res, 500, { error: "internal error" }); } catch (_) {}
    });
    return;
  }

  // v1.9c: Mail.tm account deletion is BLOCKED at the proxy, for
  // every client of every version. Two sold accounts died because a
  // DELETE /accounts reached Mail.tm; Mail.tm's own policy is that a
  // mailbox lives until the user deletes it, and MovMail never
  // deletes mailboxes (v1.7b removed the frontend calls, but an old
  // cached site on a phone could still send one). Refuse here, before
  // any forwarding — the request never reaches Mail.tm. Logged
  // best-effort (console + security_events); logging never breaks
  // the 403 response.
  if (
    req.method === "DELETE" &&
    (url.pathname === "/accounts" || /^\/accounts\/[^/]+$/.test(url.pathname))
  ) {
    console.error("movmail-proxy: blocked Mail.tm account delete:", url.pathname);
    try {
      logSecurityEvent("", "account_delete_blocked", url.pathname).catch(() => {});
    } catch (_) {}
    sendJson(res, 403, { ok: false, error: "account_delete_blocked" });
    return;
  }

  if (!isAllowed(req.method, url.pathname)) {
    sendJson(res, 404, { error: "not found" });
    return;
  }

  // GET /domains: serve from the 5-minute cache when it is fresh,
  // without touching Mail.tm at all.
  const isDomains = req.method === "GET" && url.pathname === "/domains";
  if (isDomains && domainsCache.data !== null && Date.now() - domainsCache.at < DOMAINS_CACHE_TTL_MS) {
    sendJson(res, 200, domainsCache.data);
    return;
  }

  const chunks = [];
  req.on("data", (chunk) => chunks.push(chunk));
  req.on("error", () => sendJson(res, 500, { error: "request read failed" }));
  req.on("end", async () => {
    try {
      const body = chunks.length ? Buffer.concat(chunks) : null;

      // Blocked accounts may not create Mail.tm accounts: the site
      // sends its signed-in gmail in the body or X-Movmail-Gmail.
      if (req.method === "POST" && url.pathname === "/accounts") {
        let gmailCandidate = "";
        try {
          const parsed = body && body.length ? JSON.parse(body.toString("utf8")) : {};
          gmailCandidate = String(
            parsed.gmail || parsed.address || req.headers["x-movmail-gmail"] || ""
          )
            .trim()
            .toLowerCase();
        } catch (_) {}
        if (gmailCandidate) {
          let blockedUser = null;
          try {
            blockedUser = await getUser(gmailCandidate);
          } catch (_) {}
          if (blockedUser && blockedUser.blocked) {
            sendJson(res, 403, {
              error: "account blocked",
              reason: blockedUser.blocked_reason || "This account has been blocked by the administrator.",
            });
            return;
          }
        }
      }

      const headers = { Accept: "application/json" };
      if (req.headers.authorization) headers.Authorization = req.headers.authorization;
      if (body && body.length) headers["Content-Type"] = "application/json";

      const upstreamRes = await fetch(UPSTREAM + url.pathname + url.search, {
        method: req.method,
        headers,
        body: body && body.length ? body : undefined,
      });

      const text = await upstreamRes.text();
      let data;
      try {
        data = JSON.parse(text);
      } catch (_) {
        data = null;
      }

      if (data !== null) {
        sendJson(res, upstreamRes.status, data);
      } else {
        res.writeHead(upstreamRes.status, {
          ...CORS_HEADERS,
          "Content-Type": "text/plain",
          "Content-Length": Buffer.byteLength(text),
        });
        res.end(text);
      }

      // Cache successful /domains answers for 5 minutes.
      if (isDomains && data !== null && upstreamRes.status >= 200 && upstreamRes.status < 300) {
        domainsCache = { at: Date.now(), data };
      }

      // Auto-save (fire-and-forget, never delays or fails the reply):
      // only on a successful upstream response.
      if (data !== null && upstreamRes.status >= 200 && upstreamRes.status < 300) {
        const address = addressFromRequest(req);
        if (req.method === "GET" && url.pathname === "/messages") {
          const list = Array.isArray(data)
            ? data
            : data && Array.isArray(data["hydra:member"])
              ? data["hydra:member"]
              : [];
          list.forEach((m) => {
            saveMessage(m, address, null);
          });
        } else if (req.method === "GET" && /^\/messages\/[^/]+$/.test(url.pathname)) {
          saveMessage(data, address, data);
        }
      }
    } catch (err) {
      sendJson(res, 502, { error: "upstream failed", detail: String((err && err.message) || err) });
    }
  });
});

server.listen(PORT, HOST, () => {
  console.log("movmail-proxy listening on " + HOST + ":" + PORT);
});
